using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sem.Authentication;
using Sem.Web.Data;
using Sem.Web.Runtime;
int count=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;}
var file=Path.Combine(Path.GetTempPath(),"sem-messages-"+Guid.NewGuid().ToString("N")+".db");var identity=new IdentityOptions();
try{var services=new ServiceCollection();services.AddLogging();services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+file));services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();await using var provider=services.BuildServiceProvider();await using var scope=provider.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();await SqliteStorageInitializer.InitializeAsync(db);db.Users.Add(new(){Id="synthetic-user",Email="synthetic@example.invalid",UserName="synthetic@example.invalid",DisplayName="合成人物",EmailConfirmed=true,Enabled=true,SecurityStamp="stamp"});await db.SaveChangesAsync();await MessageFixture.Seed(db);
 ClaimsPrincipal Who(string stamp="stamp",bool duplicate=false)=>new(new ClaimsIdentity(new[]{new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user"),new Claim(identity.ClaimsIdentity.SecurityStampClaimType,stamp),new Claim(AuthenticationSession.SessionClaim,"session")}.Concat(duplicate?[new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user")]:[]),"synthetic"));
 Task<MessageResult> Read(int p=0,string? id=null,bool unread=false,ClaimsPrincipal? who=null)=>MessageReader.ReadAsync(db,who??Who(),identity,p,id,unread);
 var before=File.ReadAllBytes(file);var wal=File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[];
 var first=(MessageBox)(await Read()).View!;Check(first.ActorId=="synthetic-user"&&first.Page==0&&first.Messages.Length==100&&first.HasMore,"本人100件と続きの有無");Check(first.Messages.First().Id=="m102"&&first.Messages.Last().Id=="m003","保存時刻の新しい順と安定ID順");Check(first.Messages.First().Title=="<img src=x> 合成メッセージ"&&first.Messages.First().IsRead,"件名と保存済み既読状態");var second=(MessageBox)(await Read(1)).View!;Check(second.Messages.Select(m=>m.Id).SequenceEqual(new[]{"m002","m001","m000"})&&!second.HasMore,"古い3件までページを辿れる");Check(second.Messages.Last().CreatedAt is null,"欠損時刻0を補完しない");Check(((MessageBox)(await Read(2)).View!).Messages.Length==0,"正常な空ページと失敗を分離");Check(((UnreadMessages)(await Read(unread:true)).View!).Count==52,"未読は本人全件を集計");
 var listJson=JsonSerializer.Serialize(first);foreach(var secret in new[]{"OTHER_TITLE_SENTINEL","OTHER_BODY_SENTINEL","Body","UserId","SecurityStamp","@example.invalid"})Check(!listJson.Contains(secret),"一覧に含めない "+secret);
 var body=(MessageBody)(await Read(id:"m102")).View!;Check(body.Body=="<script>合成本文</script>\n二行目"&&body.ActorId=="synthetic-user","本人だけに本文と改行");Check((await Read(id:"other-message")).State=="not-found"&&(await Read(id:"missing")).State=="not-found","他人のID参照は欠損と同じ");Check(!JsonSerializer.Serialize(body).Contains("EventId"),"元記録にないイベントを推測しない");Check(((UnreadMessages)(await Read(unread:true)).View!).Count==52,"本文を開いても未読不変");Check(before.SequenceEqual(File.ReadAllBytes(file))&&wal.SequenceEqual(File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[]),"一覧・未読・本文でDB／WAL不変");Check((await Read(-1)).State=="invalid-request"&&(await Read(int.MaxValue)).State=="invalid-request","不正ページとoverflow拒否");
 var own=await db.Messages.SingleAsync(m=>m.Id=="m102");own.Created=long.MaxValue;await db.SaveChangesAsync();Check((await Read()).State=="invalid"&&(await Read(id:"m102")).State=="invalid","範囲外時刻は不正として報告");own.Created=0;own.Body=new string('あ',65537);await db.SaveChangesAsync();Check((await Read(id:"m102")).State=="invalid","本文の安全上限超過を拒否");own.Body="合成本文";await db.SaveChangesAsync();
 Check((await Read(who:new(new ClaimsIdentity()))).State=="unauthorized","匿名拒否");Check((await Read(who:Who("old"))).State=="unauthorized","古いstamp拒否");Check((await Read(who:Who(duplicate:true))).State=="unauthorized","重複claim拒否");var actor=await db.Users.SingleAsync(u=>u.Id=="synthetic-user");actor.Enabled=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized"&&(await Read(unread:true)).State=="unauthorized","無効本人は一覧と未読拒否");actor.Enabled=true;actor.EmailConfirmed=false;await db.SaveChangesAsync();Check((await Read(id:"m102")).State=="unauthorized","メール未確認本人の本文拒否");actor.EmailConfirmed=true;await db.SaveChangesAsync();db.RevokedAuthSessions.Add(new(){UserId=actor.Id,TokenHash=AuthenticationSession.Hash("session"),RevokedAt=DateTimeOffset.UtcNow.ToString("O")});await db.SaveChangesAsync();Check((await Read(id:"m102")).State=="unauthorized","失効sessionで本文拒否");Console.WriteLine($"本人メッセージ参照・現在認証・非書込 {count}検査: 成功（合成DBのみ）");
}finally{SqliteConnection.ClearAllPools();foreach(var p in new[]{file,file+"-wal",file+"-shm"})File.Delete(p);}
